import{_ as e,c as t,o as a,a2 as o}from"./chunks/framework.BX_emVE_.js";const f=JSON.parse('{"title":"如何删除凭证","description":"","frontmatter":{},"headers":[],"relativePath":"credential/how-to-delete.md","filePath":"credential/how-to-delete.md"}'),r={name:"credential/how-to-delete.md"},l=o('<h1 id="如何删除凭证" tabindex="-1">如何删除凭证 <a class="header-anchor" href="#如何删除凭证" aria-label="Permalink to &quot;如何删除凭证&quot;">​</a></h1><div class="caution custom-block github-alert"><p class="custom-block-title">CAUTION</p><p>注销凭证属于危险操作。若您删除了凭证，凭证将无法恢复。</p></div><p>前往注销页面时，您需要知晓：</p><ul><li>您的点数将随着账号清零</li><li>您的徽章将随着账号清空</li><li>使用服务的所有记录将清空</li><li>OAuth登录的数据将清空</li></ul><p>如果您真的需要删除凭证，请首先检查<strong>您注册凭证时填写的邮箱是否还含有注册回件</strong>，这是非常重要的，在首次登录时已经提醒过您必须<strong>保存好回件</strong>。</p><p>检查回件是否包含了<strong>回件ID、凭证ID、凭证密钥、凭证创建时间</strong>这些重要信息，然后您就可以开始注销凭证了。</p><h2 id="注销流程" tabindex="-1">注销流程 <a class="header-anchor" href="#注销流程" aria-label="Permalink to &quot;注销流程&quot;">​</a></h2><p>首先登录火石凭证后，前往<a href="https://id.turboflint.cn/account/delete" target="_blank" rel="noreferrer">火石凭证注销页面</a></p><p>然后根据流程进行注销后，您将删除火石凭证。</p><h2 id="注销后的处理方式" tabindex="-1">注销后的处理方式 <a class="header-anchor" href="#注销后的处理方式" aria-label="Permalink to &quot;注销后的处理方式&quot;">​</a></h2><p>注销后，您的凭证将永久删除，包括所有服务记录和日志等，不会留有任何其他数据。</p>',11),i=[l];function n(s,c,d,h,p,_){return a(),t("div",null,i)}const m=e(r,[["render",n]]);export{f as __pageData,m as default};
